sp_widget.client_script:
api.controller = function($scope, $location, $window) {
  var c = this;
  c.step = 1;
  c.isSubmitting = false;

  // Preserve data.nationalities sent from Server Script
  c.data.fullName = c.data.fullName || '';
  c.data.email = c.data.email || '';
  c.data.dob = c.data.dob || '';
  c.data.nationality = c.data.nationality || '';
  c.data.passportNumber = c.data.passportNumber || '';
  c.data.targetCity = c.data.targetCity || '';
  c.data.visaCategory = c.data.visaCategory || '';
  c.data.jobTitle = c.data.jobTitle || '';
  c.data.salary = c.data.salary || null;
  c.data.legalConsent = c.data.legalConsent || false;

  c.data.files = {
    passport: null,
    photo: null,
    contract: null,
    degree: null
  };

  c.isValidEmail = function(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  c.fileSelected = function(element, fileType) {
    var file = element.files[0];
    if (!file) {
      c.data.files[fileType] = null;
      return;
    }

    var reader = new FileReader();
    reader.onload = function(e) {
      $scope.$apply(function() {
        var base64Data = e.target.result.split(',')[1];
        c.data.files[fileType] = {
          name: file.name,
          type: file.type,
          base64: base64Data
        };
      });
    };
    reader.readAsDataURL(file);
  };

  c.goToStep = function(targetStep) {
    if (targetStep === 2) {
      if (!c.data.fullName || !c.data.email || !c.data.dob || !c.data.nationality || !c.data.passportNumber) {
        alert('Please complete all personal details in Step 1.');
        return;
      }
      if (!c.isValidEmail(c.data.email)) {
        alert('Please provide a valid email format.');
        return;
      }
    }

    if (targetStep === 3) {
      if (!c.data.targetCity || !c.data.visaCategory || !c.data.jobTitle || !c.data.salary) {
        alert('Please fill in all relocation and employment details in Step 2.');
        return;
      }
    }

    c.step = targetStep;
  };

  c.submitApplication = function() {
    if (!c.data.legalConsent) {
      alert('Please agree to the § 81a representation authorization.');
      return;
    }

    if (!c.data.fullName || !c.data.email || !c.data.passportNumber) {
      alert('Please complete all required identity fields.');
      return;
    }

    if (!c.data.files.passport || !c.data.files.photo || !c.data.files.contract || !c.data.files.degree) {
      alert('All four document uploads (Passport, Photo, Contract, Degree) are required.');
      return;
    }

    c.isSubmitting = true;
    c.data.action = 'submit_visa_case_with_attachments';

    c.server.update().then(function(response) {
      c.isSubmitting = false;
      if (response && response.result === 'success' && response.caseSysId) {
        var path = $window.location.pathname;
        $window.location.href = path + '?id=gvft_status&sys_id=' + response.caseSysId;
      } else if (response && response.message) {
        alert('Submission error: ' + response.message);
      } else {
        alert('Submission failed. Please check your data and retry.');
      }
    });
  };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

/* Color Variables matching Retention Pulse Portal */
$page-bg: #f1f5f9;
$card-bg: #ffffff;
$header-teal: #005f73;
$accent-blue: #0284c7;
$accent-blue-hover: #0369a1;
$success-green: #10b981;
$border-light: #e2e8f0;
$input-border: #cbd5e1;
$text-dark: #0f172a;
$text-body: #334155;
$text-muted: #64748b;

/* Fixed background coverage */
.gvft-bg-layer {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: 0;
  background-color: $page-bg;
  pointer-events: none;
}

.gvft-intake-wrapper {
  position: relative;
  z-index: 1;
  font-family: 'Inter', sans-serif !important;
  min-height: 100vh;
  padding: 40px 20px 80px 20px;
}

/* Broadened Desktop Layout */
.gvft-main-container {
  max-width: 1060px !important;
  width: 95% !important;
  margin: 0 auto !important;
  position: relative;
  z-index: 2;
}

/* Card Shell */
.gvft-card {
  background: $card-bg;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid $border-light;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.08);
  width: 100%;
}

/* Top Petrol / Teal Header Banner */
.gvft-card-header {
  background-color: $header-teal;
  color: #ffffff;
  padding: 30px 32px 26px 32px;
  text-align: center;

  i {
    opacity: 0.9;
    margin-bottom: 8px;
    display: inline-block;
  }

  h2 {
    margin: 4px 0 6px 0;
    font-size: 24px;
    font-weight: 700;
    letter-spacing: 0.5px;
    color: #ffffff;
  }

  p {
    margin: 0;
    font-size: 14px;
    color: #e0f2fe;
    opacity: 0.85;
  }
}

/* Inner Body */
.gvft-card-body {
  padding: 36px 48px;
}

/* Stepper Wizard */
.gvft-wizard-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 auto 36px auto;
  max-width: 820px;
  width: 100%;
}

.step-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0.55;
  transition: all 0.25s ease;
  min-width: 110px;
  cursor: pointer;

  &.active,
  &.completed {
    opacity: 1;
  }
}

.step-circle {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #f8fafc;
  color: $text-muted;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 15px;
  border: 2px solid $input-border;
  transition: all 0.25s ease;
}

.step-item.active .step-circle {
  background: $accent-blue !important;
  color: #ffffff !important;
  border-color: $accent-blue !important;
  box-shadow: 0 0 14px rgba(2, 132, 199, 0.35);
}

.step-item.completed .step-circle {
  background: $success-green !important;
  color: #ffffff !important;
  border-color: $success-green !important;
}

.step-label {
  color: $text-muted;
  font-weight: 600;
  font-size: 13px;
  margin-top: 8px;
  text-align: center;
  white-space: nowrap;
}

.step-item.active .step-label {
  color: $header-teal !important;
}

.step-line {
  flex: 1;
  height: 2px;
  background: $border-light;
  margin: 0 12px 24px 12px;
  transition: background 0.3s ease;

  &.active {
    background: $accent-blue;
  }
}

/* Step Header */
.pane-header {
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 1px solid $border-light;
}

.step-title {
  color: $header-teal;
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 6px 0;

  i {
    color: $accent-blue;
    margin-right: 8px;
  }
}

.instruction-text {
  color: $text-muted;
  font-size: 14px;
  margin: 0;
}

/* Form Controls & Inputs */
.form-grid {
  margin-bottom: 8px;
}

.form-group {
  margin-bottom: 22px;
}

.control-label {
  color: $text-dark;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 6px;
  display: block;
}

.text-danger {
  color: #ef4444;
}

.form-control {
  background: #ffffff !important;
  border: 1px solid $input-border !important;
  color: $text-dark !important;
  border-radius: 6px !important;
  height: 44px;
  font-size: 14px;
  padding: 8px 14px;
  box-shadow: none !important;

  &:focus {
    border-color: $accent-blue !important;
    box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.15) !important;
    outline: none;
  }

  &::placeholder {
    color: #94a3b8;
  }
}

select.form-control option {
  background: #ffffff;
  color: $text-dark;
}

.uppercase-input {
  text-transform: uppercase;
}

.gvft-file-input {
  padding: 8px 12px !important;
  line-height: normal;
  background: #f8fafc !important;
  border: 1px dashed $input-border !important;
}

.file-tag {
  display: inline-block;
  margin-top: 6px;
  font-size: 12px;
  color: $header-teal;
  font-weight: 600;
  background: #e0f2fe;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid #bae6fd;

  i {
    color: $success-green;
    margin-right: 4px;
  }
}

/* Legal Power of Attorney Consent Callout */
.gvft-consent-box {
  background: #f0f7fa;
  border: 1px solid #bae6fd;
  border-left: 4px solid $header-teal;
  border-radius: 6px;
  padding: 16px 20px;
  margin-top: 20px;
  margin-bottom: 20px;

  .checkbox-container {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    margin: 0;
    cursor: pointer;
  }

  input[type="checkbox"] {
    margin-top: 3px;
    accent-color: $header-teal;
    width: 18px;
    height: 18px;
    cursor: pointer;
  }

  .consent-text {
    font-size: 13px;
    color: $text-body;
    line-height: 1.5;

    strong {
      color: $header-teal;
    }
  }
}

/* Action Buttons */
.gvft-button-row {
  margin-top: 28px;

  &.text-right {
    text-align: right;
  }

  &.between-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
}

.btn-prev {
  background: #f1f5f9 !important;
  color: $text-body !important;
  border: 1px solid $input-border !important;
  height: 44px;
  padding: 0 24px;
  border-radius: 6px;
  font-weight: 600;
  transition: all 0.2s;

  &:hover {
    background: #e2e8f0 !important;
    color: $text-dark !important;
  }
}

.btn-next {
  background: $accent-blue !important;
  color: #ffffff !important;
  border: none !important;
  height: 44px;
  padding: 0 28px;
  border-radius: 6px;
  font-weight: 700;
  transition: all 0.2s ease;

  &:hover {
    background: $accent-blue-hover !important;
    box-shadow: 0 4px 14px rgba(2, 132, 199, 0.25);
  }
}

.btn-submit {
  background: $success-green !important;
  color: #ffffff !important;
  border: none !important;
  height: 44px;
  padding: 0 32px;
  border-radius: 6px;
  font-weight: 700;
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.25);
  transition: background-color 0.2s ease;

  &:hover {
    background: darken($success-green, 8%) !important;
  }

  &[disabled] {
    opacity: 0.65;
    cursor: not-allowed;
  }
}

sp_widget.script:
(function() {

// 1. Initial Load: Populate Nationality Dropdown from core_country
  data.nationalities = [];

  var grCountry = new GlideRecord('core_country');
  grCountry.addActiveQuery();
  grCountry.orderBy('name');
  grCountry.query();

  while (grCountry.next()) {
    data.nationalities.push({
      label: grCountry.getValue('name'),
      value: grCountry.getValue('name')
    });
  }

  // 1b. German Cities List
  data.germanCities = [
    'Berlin',
    'Munich',
    'Frankfurt am Main',
    'Hamburg',
    'Cologne (Köln)',
    'Stuttgart',
    'Düsseldorf',
    'Leipzig',
    'Dresden',
    'Nuremberg (Nürnberg)',
    'Hanover (Hannover)',
    'Bonn',
    'Essen',
    'Dortmund',
    'Mannheim',
    'Karlsruhe',
    'Aachen',
    'Other / Remote'
  ];

  if (input && input.action === 'submit_visa_case_with_attachments') {
    data.result = 'pending';

    var caseTable = 'x_2023506_german_1_imm_case';
    var docTable  = 'x_2023506_german_1_case_doc';

    try {
      var gr = new GlideRecord(caseTable);
      gr.initialize();

      // 1. Set Parent Case fields
      gr.setValue('u_candidate_name', input.fullName);
      gr.setValue('u_candidate_email', String(input.email).trim().toLowerCase());
      gr.setValue('u_candidate_dob', input.dob);
      gr.setValue('u_nationality', input.nationality);
      gr.setValue('u_passport_number', String(input.passportNumber).toUpperCase().trim());
      gr.setValue('u_target_city', input.targetCity);
      gr.setValue('u_visa_category', input.visaCategory);
      gr.setValue('u_job_title', input.jobTitle);
      gr.setValue('u_annual_salary', input.salary);
      gr.setValue('u_fast_track_authorized', input.legalConsent);
      gr.setValue('state', '1'); // 1 = Open
      gr.setValue('u_fee_status', 'Pending');

      var caseSysId = gr.insert();

      if (!caseSysId) {
        data.result = 'error';
        data.message = 'Could not insert case record in ' + caseTable;
        return;
      }

      gr.get(caseSysId);
      data.result = 'success';
      data.caseSysId = caseSysId;


      var attachmentWriter = new GlideSysAttachment();

      // 2. Child doc helper using exact Choice Values ('1', '2', '3', '4')
      function createCaseDocument(choiceValue, labelText, fileObj) {
        if (!fileObj || !fileObj.base64) return;

        var grDoc = new GlideRecord(docTable);
        grDoc.initialize();
        grDoc.setValue('u_case', caseSysId);
        grDoc.setValue('u_document_name', choiceValue);
        grDoc.setValue('u_file_name', fileObj.name);
        grDoc.setValue('u_status', 'Submitted');
        grDoc.setValue('u_review_notes', 'Pending initial caseworker verification');
        var docSysId = grDoc.insert();

        var mimeType = fileObj.type || 'application/pdf';

        // Attach directly to the child document record
        if (docSysId && grDoc.get(docSysId)) {
          var childAttachId = attachmentWriter.writeBase64(grDoc, fileObj.name, mimeType, fileObj.base64);
          if (childAttachId && grDoc.isValidField('u_attachment')) {
            grDoc.setValue('u_attachment', childAttachId);
            grDoc.update();
          }
        }

        // Attach also to parent case record
        attachmentWriter.writeBase64(gr, labelText + ' - ' + fileObj.name, mimeType, fileObj.base64);
      }

      // 3. Process all 4 uploaded files
     if (input.files) {
        createCaseDocument('Passport',           'Passport',           input.files.passport);
        createCaseDocument('Passport Photo',     'Passport Photo',     input.files.photo);
        createCaseDocument('Job Contract',       'Job Contract',       input.files.contract);
        createCaseDocument('Degree Certificate', 'Degree Certificate', input.files.degree);
      }

      data.caseNumber = gr.getValue('number');

    } catch (ex) {
      data.result = 'error';
      data.message = 'Server execution failure: ' + ex.message;
    }
  }
})();
